/// Expect a Fight (Uncommon, 2 energy, Self). Faithful to C#
/// `ExpectAFight.OnPlay`: gain energy equal to the number of `Attack` cards in
/// hand (`CalculatedVar` multiplier counts hand Attacks), then apply
/// `NoEnergyGainPower(1)`. Bead `sts2-rs-o7d5d` (prior port counted Skills and
/// never applied NoEnergyGain).
///
/// C# `ModifyEnergyGain → 0` suppression of *subsequent* energy gains is now
/// enforced: `CombatState::gain_energy` checks for `NoEnergyGain` active and
/// returns early with no gain (bead sts2-rs-yb8m). This card's own energy gain
/// happens BEFORE the power is applied (matching C# order), so that part is
/// unaffected by the suppression.
/// `CalculatedEnergy`: `CalculationBase(0) + CalculationExtra(1) x <Attacks in
/// your Hand>`. Shared with the card face — see `crate::cards::preview`.
pub(crate) fn preview_expect_a_fight(
    state: &CombatState,
    _card: &Card,
    _target: Option<CreatureUid>,
) -> i32 {
    state
        .player
        .hand
        .iter()
        .copied()
        .filter(|u| {
            let idx = u.0.get() as usize - 1;
            state.cards[idx].card_type == CardType::Attack
        })
        .count()
        .try_into()
        .unwrap_or(0)
}

pub(crate) fn play_expect_a_fight(
    state: &mut CombatState,
    _t: Option<CreatureUid>,
) -> EffectResult {
    let attack_count = resolving_preview(state, preview_expect_a_fight, None);
    // C# routes the gain through `PlayerCmd.GainEnergy` (PlayerCmd.cs:24-37),
    // which fires `Hook.ModifyEnergyGain` and clamps; direct `+=` mutation
    // bypassed both. NoEnergyGain is applied AFTER this gain, so the card's
    // own gain still lands (matching C# order). Bead `sts2-rs-o1bbi`
    // (LOUSE_PROGENITOR_NORMAL_player_energy).
    state.gain_energy(attack_count);
    apply_power_to_player(state, PowerKind::NoEnergyGain, 1);
    EffectResult::Resolved
}

